import (
	stdin, stdout from "@std/io/io.ms",
	lines from "@std/io/streams.ms",
)

fn run() Result[Unit, Error]:
	var input = lines(stdin())

	while true:
		line := try input.next()

		if text := line:
			try stdout().write("{text}\n")
		else:
			break

	return stdout().flush()

fn main() Unit!:
	try run()
